// 不建立内层保存点；每条命令的Common、Shop、清算、Task全写集由原World候选拥有。
#include "private_shop_liquidation_integration.hpp"
#include "world_bundle.hpp"
namespace hanmo::resident {namespace {
Status available(const WorldBundle& w){
 if(!w.private_shop_liquidations_enabled()||!w.task_shop_orders_enabled()||!w.tasks.shop_orders||!w.tasks.shop_orders->estate_cancellations||!w.private_shop_liquidations_seed_complete||!w.private_shops_enabled()||!w.private_shops_seed_complete||!w.family_life_enabled()||!w.catalog->common||!w.catalog->tasks||!w.catalog->interaction||!w.catalog->task_message_notices||!w.tasks.message_notices||!w.tasks.message_handoffs)return common_failure("PrivateShopLiquidationProfileRequired");return common_success();
}
bool identity(const WorldIdentity& a,const WorldIdentity& b){return a.world_id==b.world_id&&a.execution_epoch==b.execution_epoch&&a.revision==b.revision&&a.tick==b.tick;}
Status player(const WorldBundle& w,const StableId& actor,const StableId& kind){auto guarded=command_common_guard(w,actor,kind);if(!guarded.ok)return guarded;return actor==w.common.state().metadata.player_actor_id?common_success():common_failure("PrivateShopExecutorPlayerCommandRequired");}
}
PrivateShopLiquidationWorldAccess::PrivateShopLiquidationWorldAccess(const WorldBundle& w,std::unique_ptr<PrivateShopWorldAccess> shops,TaskMessageNoticeServices notices)
 :world_(w),shops_(std::move(shops)),notices_(std::move(notices)),
 context_{w.common,*w.catalog->common,w.private_shops,*w.catalog->private_shops,w.private_shop_liquidations,*w.catalog->private_shop_liquidations,*w.catalog->interaction,w.family_life,w.family_death_read(),[this](const StableId& observer,const StableId& binding){return read_delivered_task_death_notice(world_.common,world_.tasks,*world_.catalog->tasks,*world_.catalog->common,*world_.catalog->task_message_notices,*world_.tasks.message_notices,*world_.tasks.message_handoffs,notices_.validate,observer,binding);}},cancellations_(context_){}
Outcome<std::unique_ptr<PrivateShopLiquidationWorldAccess>> PrivateShopLiquidationWorldAccess::create(const WorldBundle& w){auto ready=available(w);if(!ready.ok)return {false,{},ready.error};auto shops=PrivateShopWorldAccess::create(w);if(!shops.ok)return {false,{},shops.error};auto notices=make_task_message_notice_services(w);if(!notices.ok)return {false,{},notices.error};if(!notices.value)return {false,{},common_failure("PrivateShopEstateNoticeProfileRequired").error};return {true,std::unique_ptr<PrivateShopLiquidationWorldAccess>{new PrivateShopLiquidationWorldAccess(w,std::move(shops.value),std::move(*notices.value))},{}};}
Status initialize_private_shop_liquidation_world_in_candidate(WorldBundle& w){if(!w.private_shop_liquidations_enabled())return common_success();if(w.common.tick()!=0||!w.task_shop_orders_enabled()||!w.tasks.shop_orders||w.tasks.shop_orders->estate_cancellations||w.private_shop_liquidations_seed_complete||!w.private_shops_seed_complete||!w.family_life_enabled()||!w.catalog->task_message_notices||!w.tasks.message_notices||!w.tasks.message_handoffs)return common_failure("PrivateShopLiquidationInitialBoundaryRequired");if(!compare_boundary(encode_private_shop_liquidations(w.private_shop_liquidations),encode_private_shop_liquidations(PrivateShopLiquidationState{})).exact())return common_failure("PrivateShopLiquidationInitialHistoryExists");auto shape=validate_private_shop_liquidation_layout(w.common,nullptr);if(!shape.ok)return shape;auto routes=validate_private_shop_liquidation_notice_routes(*w.catalog->private_shop_liquidations,*w.catalog->tasks,*w.catalog->task_message_notices);if(!routes.ok)return routes;w.tasks.shop_orders->estate_cancellations.emplace();w.private_shop_liquidations_seed_complete=true;return common_success();}
Status validate_private_shop_liquidation_world(const WorldBundle& w){auto pair=validate_private_shop_liquidation_pair(w.private_shop_liquidations_enabled(),w.catalog->identity.module_versions);if(!pair.ok)return pair;auto task_layout=validate_task_shop_order_estate_layout(w.common,w.private_shop_liquidations_enabled(),w.catalog->identity.module_versions,w.tasks.shop_orders?&*w.tasks.shop_orders:nullptr);if(!task_layout.ok)return task_layout;Integer markers=0;for(const auto& m:w.catalog->identity.module_versions)if(m.first==private_shop_liquidation_module){if(m.second!="1"||++markers!=1)return common_failure("PrivateShopLiquidationProfileMismatch");}const bool enabled=w.private_shop_liquidations_enabled();if(markers!=(enabled?1:0)||enabled!=w.private_shop_liquidations_seed_complete)return common_failure("PrivateShopLiquidationProfileMismatch");if(!enabled){if(!compare_boundary(encode_private_shop_liquidations(w.private_shop_liquidations),encode_private_shop_liquidations(PrivateShopLiquidationState{})).exact())return common_failure("UnexpectedPrivateShopLiquidationState");auto task_cache=validate_task_shop_order_estate_cached_results(w.common,nullptr);return task_cache.ok?validate_private_shop_liquidation_cached_results(w.common,nullptr):task_cache;}auto access=PrivateShopLiquidationWorldAccess::create(w);if(!access.ok)return {false,{},access.error};auto routes=validate_private_shop_liquidation_notice_routes(*w.catalog->private_shop_liquidations,*w.catalog->tasks,*w.catalog->task_message_notices);if(!routes.ok)return routes;auto valid=validate_private_shop_estate_closings(access.value->shops().context(),access.value->context());if(!valid.ok)return valid;valid=validate_task_shop_order_estate_cancellations(w.common,w.tasks,*w.tasks.shop_orders,access.value->cancellations());if(!valid.ok)return valid;valid=validate_task_shop_order_estate_cached_results(w.common,&*w.tasks.shop_orders->estate_cancellations);return valid.ok?validate_private_shop_liquidation_cached_results(w.common,&w.private_shop_liquidations):valid;}
Outcome<PrivateShopLiquidationQuote> prepare_private_shop_liquidation_world(const WorldBundle& w,const StableId& actor,const PrivateShopLiquidationCommand& command){auto guarded=player(w,actor,private_shop_liquidation_command_kind(command));if(!guarded.ok)return {false,{},guarded.error};auto access=PrivateShopLiquidationWorldAccess::create(w);if(!access.ok)return {false,{},access.error};return preview_private_shop_liquidation_command(access.value->shops().context(),access.value->context(),access.value->shops().meeting(),actor,command);}
Outcome<PrivateShopWorldCommit> commit_private_shop_liquidation_world(WorldBundle& w,const StableId& actor,const PrivateShopLiquidationCommand& command,const PrivateShopLiquidationQuote& quote){
 auto guarded=player(w,actor,private_shop_liquidation_command_kind(command));if(!guarded.ok)return {false,{},guarded.error};if(actor!=quote.actor_id||!identity(quote.source_identity,w.common.state().identity)||!compare_boundary(encode_private_shop_liquidation_command(command),encode_private_shop_liquidation_command(quote.command)).exact()||private_shop_liquidation_command_kind(command)!=private_shop_liquidation_command_kind(quote.command))return {false,{},common_failure("StalePrivateShopExecutorQuote").error};auto access=PrivateShopLiquidationWorldAccess::create(w);if(!access.ok)return {false,{},access.error};auto& read=*access.value;auto current=preview_private_shop_liquidation_command(read.shops().context(),read.context(),read.shops().meeting(),actor,command);if(!current.ok)return {false,{},current.error};if(!compare_boundary(encode_private_shop_liquidation_quote(current.value),encode_private_shop_liquidation_quote(quote)).exact())return {false,{},common_failure("StalePrivateShopExecutorQuote").error};StableId source;
 if(std::holds_alternative<PrivateShopEstateClose>(command)){const auto* close=std::get_if<PrivateShopEstateClosingQuote>(&current.value.data);if(!close)return {false,{},common_failure("PrivateShopEstateQuoteKindMismatch").error};auto result=close_private_shop_estate_in_candidate(w.common,w.private_shops,w.private_shop_liquidations,read.shops().context(),read.context(),*close);if(!result.ok)return {false,{},result.error};source=result.value;}
 else {const auto* decision=std::get_if<PrivateShopExecutorQuote>(&current.value.data);if(!decision)return {false,{},common_failure("PrivateShopEstateQuoteKindMismatch").error};auto result=apply_private_shop_executor_in_candidate(w.common,w.private_shop_liquidations,read.context(),read.shops().meeting(),w.services,*decision);if(!result.ok)return {false,{},result.error};source=result.value.revocation_fact_id.empty()?result.value.mandate_fact_id:result.value.revocation_fact_id;}
 auto valid=validate_private_shop_estate_closings(read.shops().context(),read.context());if(!valid.ok)return {false,{},valid.error};return {true,{source,{}},{}};
}
Outcome<BoundaryValue> query_private_shop_liquidation_world(const WorldBundle& w,const PrivateShopLiquidationViewQuery& query){auto access=PrivateShopLiquidationWorldAccess::create(w);if(!access.ok)return {false,{},access.error};auto preview=[&w](const StableId& actor,const PrivateShopLiquidationCommand& command){return prepare_private_shop_liquidation_world(w,actor,command);};auto orders=[&w](const StableId& actor,const TaskShopOrderEstateCancel& command){return prepare_task_shop_order_estate_world(w,actor,command);};return query_private_shop_liquidations(access.value->context(),access.value->shops().meeting(),preview,query,orders);}
Status bind_private_shop_liquidation_result_world(WorldBundle& w,const PrivateShopLiquidationState& before,const StableId& actor,Integer sequence,const CommitResult& result){if(!w.private_shop_liquidations_enabled())return validate_private_shop_liquidation_cached_results(w.common,nullptr);auto fresh=private_shop_liquidation_new_command_sources(before,w.private_shop_liquidations);if(!fresh.ok)return {false,{},fresh.error};return bind_private_shop_liquidation_result_in_candidate(w.common,w.private_shop_liquidations,fresh.value,actor,sequence,result);}
Outcome<TaskShopOrderEstateCancellationQuote> prepare_task_shop_order_estate_world(const WorldBundle& w,const StableId& actor,const TaskShopOrderEstateCancel& command){auto guarded=player(w,actor,task_shop_order_estate_cancel_command);if(!guarded.ok)return {false,{},guarded.error};auto access=PrivateShopLiquidationWorldAccess::create(w);if(!access.ok)return {false,{},access.error};return preview_task_shop_order_estate_command(w.common,w.tasks,*w.tasks.shop_orders,access.value->shops().orders(),access.value->cancellations(),actor,command);}
Outcome<InteractionEffect> commit_task_shop_order_estate_world(WorldBundle& w,const StableId& actor,const TaskShopOrderEstateCancel& command,const TaskShopOrderEstateCancellationQuote& quote){auto guarded=player(w,actor,task_shop_order_estate_cancel_command);if(!guarded.ok)return {false,{},guarded.error};auto access=PrivateShopLiquidationWorldAccess::create(w);if(!access.ok)return {false,{},access.error};auto capture=[&](const PrivateShopOrderExecution& source)->Status{auto recorded=capture_private_shop_order_execution_in_candidate(w.common,w.private_shops,access.value->shops().context(),source.order_id);return recorded.ok?common_success():Status{false,{},recorded.error};};auto result=commit_task_shop_order_estate_business_in_candidate(w.common,w.tasks,*w.tasks.shop_orders,access.value->shops().orders(),access.value->cancellations(),actor,command,quote,capture);if(!result.ok)return result;auto valid=validate_private_shop_estate_closings(access.value->shops().context(),access.value->context());return valid.ok?result:Outcome<InteractionEffect>{false,{},valid.error};}
Status bind_task_shop_order_estate_result_world(WorldBundle& w,const TaskShopOrderEstateCancellationState* before,const StableId& actor,Integer sequence,const CommitResult& result){auto* after=w.tasks.shop_orders&&w.tasks.shop_orders->estate_cancellations?&*w.tasks.shop_orders->estate_cancellations:nullptr;if(!before&&!after)return validate_task_shop_order_estate_cached_results(w.common,nullptr);if(result.kind==task_shop_order_estate_cancel_command&&!result.details)return common_failure("TaskShopOrderEstateActualResultRequired");const ReceiptDetails empty;auto source=task_shop_order_estate_new_player_source(before,after,actor,result.kind,result.details?*result.details:empty,result.tick);if(!source.ok)return {false,{},source.error};if(!after)return validate_task_shop_order_estate_cached_results(w.common,nullptr);return bind_task_shop_order_estate_player_result(w.common,*after,source.value,actor,sequence,result);}

}
